    "lessonTitle": "Lesson 1: Story: The Lion and the Mouse",
    "title": "The Lion and the Mouse",
    "sourceText": "Once upon a time, a mighty lion was sleeping peacefully in a deep jungle. A tiny mouse began playing nearby and ran over the lion's nose. The lion woke up angrily and caught the little mouse in his huge paw. The mouse pleaded, 'O King of the jungle! Please forgive me this time. I will never forget your kindness. Maybe one day I can help you!' The lion laughed at the idea of a tiny mouse helping him, but let him go. A few days later, the lion was caught in a hunter's strong rope net. He roared loudly in helplessness. Hearing the roar, the little mouse ran quickly to the spot. Using his sharp little teeth, the mouse chewed through the heavy ropes and set the lion free. From that day on, the lion and the mouse became lifelong friends.",
