    "title": "The Food Pyramid",
    "sourceText": "What food is good food? Sometimes the food we like to eat isn't the healthiest food for us. The Food Pyramid helps us understand the different food groups, and it tells us how much of each food group we should eat. Look at the bottom of the Food Pyramid. These are foods made from grain, for example, rice, ruti and bread. Potatoes are not grains, but they are similar. Grains give us energy. Fruit and vegetables are in the next level. These are also very important for us. They have vitamins. They help our eyes and our health. On the next level, there are fish, meat, dairy products, beans and lentils. Meat, fish and chicken have protein. Beans and lentils do, too! Dairy products are things like milk and egg. They help our teeth and bones. Fat and oil are at the top of the Food Pyramid. These make food delicious, but our body does not need very much of them.",
