    "lessonTitle": "Unit 10: My Home District - Kishoreganj",
    "title": "Kishoreganj",
    "sourceText": "My home district is Kishoreganj. It is about 145 kilometres from Dhaka. It is an administrative district. The district has 8 municipalities, 13 upazilas, 108 unions and 1745 villages. The name Kishoreganj comes from the name of an old landlord known as Brojosundor Roy or Brojokishore Roy. The area of Kishoreganj municipality is about 10 square kilometres. The river Narasunda flows through the town. Kishoreganj is a small town, but there are many important places in and around it. The largest Eid fairgrounds, called Solakia Eid Ground, and the well-known Pagla Mosque are in this district. Outside the town, you can visit the fort of Isah Khan at Jangalbari. You can also see the Shah Muhammad Mosque at Egaroshindhur. Kishoreganj is also the birthplace of some famous people. Chandrabati, the first woman poet of Bangla literature, was born here. Two writers of children's literature, Upendrakishore Roy Chowdhury and Sukumar Ray, were also from here. The great painter Zainul Abedin comes from Kishoreganj, too. Syed Nazrul Islam, the first acting President of Bangladesh, is also from here. I love my home district!",
