    "lessonTitle": "Unit 12: How Far is Saint Martin's? - Coral Island",
    "title": "Coral Island",
    "sourceText": "Saint Martin's Island is a special place in Bangladesh. It is the only coral island in Bangladesh, and you can see coral in different shapes and colours. The water in the Bay of Bengal is very clean and blue! You can also see the turtles on the island. The turtles make their nests on the beach and then they lay their eggs in them. You can see many fish, too. You can go on a wooden boat or a sea truck to get there. The journeys from Teknaf to Saint Martin's Island are exciting. You can see the green hills of Myanmar on one side and the blue sea on the other. It takes about two to two and a half hours to reach the island. You can drink sweet coconut water and eat delicious sea fish there. The island is peaceful and clean.",
