    "title": "Unit 14: Story: The Hare and the Tortoise",
    "sourceText": "One day, a hare was walking in the forest when he saw a tortoise. The hare was the fastest animal in the forest. The tortoise was the slowest animal in the forest. The hare called out to the tortoise, \"Hurry up! You are so slow! Can't you walk faster? Can't you run?\" The tortoise felt angry and said, \"Why don't we have a race? Maybe I can win!\" The hare laughed and laughed. \"Sure! I will win!\" the hare said. They agreed to start next to a big tree and finish at the river. Then they began their race. The hare ran as fast as he could. In a few minutes the hare was out of sight. The hare said to himself, \"The tortoise is very far behind. I can walk a bit, and then I can have a nap.\" Soon the hare was asleep under a tree next to the path. The tortoise walked steadily on and on. He didn't stop. Soon, he passed the sleeping hare. The hare slept for an hour. When he woke up, he looked at the finish line. He could not believe his eyes! The tortoise was almost at the finish line! The hare ran as fast as he could, but it was too late. The tortoise crossed the finish line and won the competition. The tortoise looked back at the hare and smiled. \"Slow and steady wins the race,\" he said.",
