    "unitTitle": "Unit 19: The Liberation War Museum",
    "lessonId": "c5-e-u19-l1",
    "lessonTitle": "Unit 19: The Liberation War Museum - A Field Trip",
    "title": "A Field Trip",
    "sourceText": "On 14 December, our class went on a field trip to the Liberation War Museum at Segunbagicha, Dhaka. The trip was planned as part of our Bangladesh and Global Studies course. Our bus reached the museum at 10 a.m. A guide was waiting for us. He welcomed us warmly and took us on a quick tour of the different galleries. At first we watched a video clip on our liberation war and our independence. There were four permanent galleries that exhibited rare photographs, documents and newspaper clippings, and objects used by the freedom fighters and the martyrs of our liberation war. At 'Gallery 2 - Our Rights, Our Sacrifices', our teacher read out to us the Declaration of Independence by Bangabandhu Sheikh Mujibur Rahman. Some other visitors also stopped and listened attentively. As we went inside 'Gallery 4 - Our Victory, Our Values', we fell silent. We were sad as we looked at the personal belongings of some of our martyred intellectuals and freedom fighters - a pair of glasses, a pen, a notebook, a money-bag, a soiled shirt and other such things. We left the museum at 12:30 p.m. It was an experience we would never forget.",
