    "title": "Cub Camporee in Sreemangal",
    "sourceText": "Last January, I went to a cub camporee. It was my first visit to a camporee and it was my first time away from home! A camporee is a gathering of cubs from different parts of Bangladesh. Cubs all over the world have their own camporees. The cub camporee took place in Sreemangal, under Moulvibazar district. To get there, we travelled from Sylhet to Sreemangal by train. We arrived in the morning, so the weather was nice. We walked to our camp from the train station. There were 10 of us in our group, plus two leaders. We were a big group, so we didn't take any rickshaws. We walked together in our group. It wasn't very far. At the camp, we cleaned up the area, set up our tents and prepared our breakfast. For breakfast, we cooked eggs and khichuri. After breakfast, we played games with cubs from other parts of Bangladesh. Then we had lunch. We cooked rice and chicken. In the afternoon and evening, we sang songs and recited poems. It was great fun! At night, we slept in our tents.",
