    "title": "রাজা ও তাঁর তিন কন্যা",
    "sourceText": "অনেক দিন আগের কথা। এক দেশে ছিল এক রাজা। রাজার ছিল তিন কন্যা—শিমুল, বকুল ও পারুল। একদিন রাজা তিন কন্যাকে ডেকে জিজ্ঞেস করলেন, 'তোমরা কে আমাকে কেমন ভালোবাসো?' বড় কন্যা শিমুল বলল, 'বাবা, আমি তোমাকে চিনির মতো ভালোবাসি।' মেজ কন্যা বকুল বলল, 'আমি তোমাকে মিষ্টির মতো ভালোবাসি।' ছোট কন্যা পারুল বলল, 'বাবা, আমি তোমাকে নুনের মতো ভালোবাসি।' এ কথা শুনে রাজা খুব রেগে গেলেন। পারুলকে বনবাসে পাঠিয়ে দিলেন। গভীর বনে পরীরা পারুলকে যত্ন করল। একদিন রাজা শিকারে গিয়ে পথ হারিয়ে ফেললেন এবং খুব ক্ষুধার্ত হলেন। পরীরা রাজাকে নানান পদের সুস্বাদু রান্না পরিবেশন করল। কিন্তু কোনো খাবারে নুন দেওয়া ছিল না। রাজা কোনো খাবারই খেতে পারলেন না। তখন রাজার ভুল ভাঙল এবং তিনি বুঝলেন, নুন ছাড়া কোনো খাবারই ভালো লাগে না। রাজা পারুলকে পরম স্নেহে বুকে জড়িয়ে নিলেন।",
