    "sourceText": "১৯৭১ সালের ১৮ই এপ্রিল। ব্রাহ্মণবাড়িয়ার দরুইন গ্রামে পাকিস্তানি সেনারা মুক্তিযোদ্ধাদের ওপর অতর্কিত আক্রমণ করল। পাকিস্তানি বাহিনীর ভারী গোলাবর্ষণ ও আধুনিক অস্ত্রের মুখে মুক্তিযোদ্ধারা কোণঠাসা হয়ে পড়লেন। মুক্তিযোদ্ধাদের সামনে তখন একটাই পথ—পিছু হটে নিরাপদ আশ্রয়ে যাওয়া। কিন্তু পিছু হটতে গেলেও কাউকে না কাউকে সমানে গুলি চালিয়ে শত্রুদের ঠেকিয়ে রাখতে হবে। এই মরণপণ দায়িত্ব একাই নিজের কাঁধে তুলে নিলেন তরুণ মুক্তিযোদ্ধা ল্যান্স নায়েক মোস্তফা কামাল। তিনি সহযোদ্ধাদের বললেন, 'তোমরা দ্রুত পিছু হটো, আমি ওদের আটকে রাখছি।' তিনি একাই ট্রেঞ্চে বসে অবিরাম মেশিনগান চালাতে লাগলেন। তাঁর প্রচণ্ড আক্রমণের মুখে পাকিস্তানি সেনারা থমকে গেল এবং এই সুযোগে সকল সহযোদ্ধা নিরাপদে পিছু হটতে পারলেন। কিন্তু একসময় মোস্তফা কামালের সব গুলি শেষ হয়ে গেল। পাকিস্তানি বাহিনীর বুলেটে তিনি শহীদ হলেন। নিজের জীবন বিলিয়ে দিয়ে তিনি বাঁচিয়েছিলেন বহু সহযোদ্ধার প্রাণ।",
