    "lessonTitle": "ষড়ঋতুর রূপ ও বৈচিত্র্য",
    "title": "বাংলাদেশের প্রকৃতি",
    "sourceText": "আমাদের প্রিয় মাতৃভূমি বাংলাদেশ ষড়ঋতুর দেশ। প্রতি দুই মাস পর পর এখানে ঋতু বদল হয়। বছরের প্রথম ঋতু হলো গ্রীষ্মকাল। বৈশাখ ও জ্যৈষ্ঠ এ দুমাস নিয়ে গ্রীষ্ম। এ সময় প্রচণ্ড গরম পড়ে, মাঠঘাট রোদে ফেটে চৌচির হয়। কিন্তু গ্রীষ্মেই পাওয়া যায় নানা রকম সুস্বাদু রসালো ফল—আম, জাম, কাঁঠাল, লিচু ইত্যাদি। গ্রীষ্মের পরই আসে বর্ষাকাল। আষাঢ় ও শ্রাবণ এ দুমাস বর্ষা। বর্ষায় আকাশ জুড়ে কালো মেঘের ঘনঘটা দেখা যায়, ঝমঝম করে বৃষ্টি নামে। খাল-বিল পানিতে থৈথৈ করে। এ সময় কদম, কেয়া ও বকুল ফোটে। এরপর আসে শরৎকাল। ভাদ্র ও আশ্বিন মাসে শরতের নীল আকাশে সাদা মেঘের ভেলা ভেসে বেড়ায়। নদীর তীরে ফোটে সাদা কাশফুল। কার্তিক ও অগ্রহায়ণ মাসে আসে হেমন্ত। হেমন্তে মাঠে মাঠে সোনালি ধান পাকে, কৃষকের ঘরে শুরু হয় নবান্ন উৎসব। পৌষ ও মাঘ মাসে শীতকাল। শীতে চারদিক কুয়াশায় ঢেকে যায় এবং ঘরে ঘরে পিঠাপুলির ধুম পড়ে। ফাল্গুন ও চৈত্র মাসে আসে ঋতুরাজ বসন্ত। দখিনা হাওয়া বয়, গাছে নতুন পাতা গজায় এবং কোকিল মধুর সুরে গান গায়। এভাবে ঋতু পরিবর্তনের সাথে সাথে আমাদের দেশের প্রকৃতি অপরূপ রূপ ধারণ করে।",
