    "sourceText": "আমাদের দেশের দক্ষিণে রয়েছে সুবিশাল বন সুন্দরবন। সুন্দরবনের ভেতরে রয়েছে নানা রকম গাছপালা ও বন্যপ্রাণী। সুন্দরবনের গাছপালা প্রাকৃতিক নিয়মে জন্মায়। সুন্দরবন থেকে যারা সরকারি অনুমতি নিয়ে গোলপাতা সংগ্রহ করেন, তাদের বলা হয় বাওয়ালি। বাওয়ালিদের কাজ অত্যন্ত ঝুঁকিপূর্ণ ও কষ্টকর। সুন্দরবনের নদী ও খালে রয়েছে ভয়ংকর কুমির আর কামট। আর বনের ভেতরে লুকিয়ে থাকে হিংস্র বাঘ—রয়েল বেঙ্গল টাইগার। বাওয়ালিরা দল বেঁধে নৌকায় করে বনে যান। রাতে তারা নৌকার ওপরই ঘুমান, কারণ ডাঙায় বাঘের ভয় থাকে। এছাড়া সুন্দরবনে মিষ্টি খাওয়ার পানির বড় অভাব। তাই সঙ্গে করে কয়েকদিনের জন্য খাবার পানি নিয়ে যেতে হয়। একটু অসাবধান হলেই বাঘের থাবায় প্রাণ হারাতে হতে পারে। জীবনের ঝুঁকি নিয়ে বাওয়ালিরা আমাদের জন্য গোলপাতা ও জ্বালানি কাঠ সংগ্রহ করে আনেন। তাঁদের এই কঠোর পরিশ্রমের মাধ্যমেই সুন্দরবনের ওপর নির্ভরশীল নানা অর্থনীতি সচল থাকে।",
