    "sourceText": "সার্থক জনম আমার জন্মেছি এই দেশে। কবীর এ কথার মর্ম আমরা অনুধাবন করতে পারি যখন আমাদের এই প্রিয় দেশের রূপবৈচিত্র্য ও মানুষের ভালোবাসার দিকে তাকাই। বাংলাদেশে কত রকমের মানুষের বাস! অধিকাংশ মানুষ বাংলায় কথা বলে, কিন্তু এর বাইরেও রয়েছে নানা ক্ষুদ্র জাতিগোষ্ঠী। যেমন—চাকমা, মারমা, গারো, ত্রিপুরা, সাঁওতাল ও ওঁরাও। প্রত্যেকের রয়েছে নিজস্ব ভাষা, নিজস্ব সংস্কৃতি ও পোশাক। এ দেশের মানুষ নানা পেশায় নিয়োজিত—কেউ কৃষক, কেউ জেলে, কেউ তাঁতি, কেউ আবার চাকরিজীবী। সবাই মিলেমিশে কাজ করে বলেই এ দেশ এগিয়ে চলেছে। আমাদের দেশে রয়েছে নানা ধর্মের মানুষ—মুসলমান, হিন্দু, বৌদ্ধ ও খ্রিস্টান। কিন্তু সবাই একই দেশের নাগরিক। মুসলমানদের ধর্মীয় উৎসব ঈদ, হিন্দুদের দুর্গোৎসব, বৌদ্ধদের বুদ্ধ পূর্ণিমা আর খ্রিস্টানদের বড়দিন। এছাড়া বাংলা নববর্ষ পহেলা বৈশাখ হলো সব বাঙালির প্রাণের মিলনমেলা। এই যে বৈচিত্র্যের মাঝেও একতা ও পারস্পরিক সৌহার্দ্য—এটাই হলো আমাদের বাংলাদেশের সবচেয়ে বড় শক্তি ও সৌন্দর্য। দেশ হলো মায়ের মতো। মা যেমন স্নেহ-মমতা ও ভালোবাসা দিয়ে আমাদের আগলে রাখেন, দেশও তেমনি তাঁর আলো, বাতাস ও শস্য দিয়ে আমাদের বাঁচিয়ে রাখে। তাই দেশকে মনেপ্রাণে ভালোবাসা আমাদের পরম কর্তব্য।",
