    "lessonId": "c5-b-l5",
    "lessonTitle": "সুন্দরবনের রয়েল বেঙ্গল টাইগার ও জীববৈচিত্র্য",
    "title": "সুন্দরবনের প্রাণী",
    "sourceText": "বাংলাদেশের দক্ষিণে অবস্থিত সুন্দরবন পৃথিবীর অন্যতম সেরা ও বৃহত্তম ম্যানগ্রোভ বন। সুন্দরবনের প্রাকৃতিক পরিবেশ অদ্ভুত ও মোহনীয়। এই বনের প্রধান ও বিশ্ববিখ্যাত প্রাণী হলো রয়েল বেঙ্গল টাইগার বা বাঘ। এই বাঘ দেখতে যেমন সুন্দর, তেমনি এর চলাফেরা ও গর্জনে রয়েছে রাজকীয় ভাব। সুন্দরবনের কর্দমাক্ত মাটিতে বাঘ নিঃশব্দে হেঁটে শিকার ধরে। এছাড়া সুন্দরবনে রয়েছে চোখজুড়ানো মায়াবী চিত্রা হরিণ। এদের গায়ে সাদা সাদা গোল দাগ থাকে এবং এরা দল বেঁধে চরে বেড়ায়। সুন্দরবনের গাছে গাছে দেখা যায় হাজারো প্রজাতির পাখি আর বানরের দুষ্টুমি। নদী ও খালের পানিতে রয়েছে কুমির ও শুশুক। অতীতে সুন্দরবনে গণ্ডার, বুনো হাতি ও বুনো মহিষ বাস করত। কিন্তু নির্মম শিকারি ও পরিবেশ ধ্বংসের কারণে আজ তারা এ দেশ থেকে চিরতরে বিলুপ্ত হয়ে গেছে। বর্তমানে রয়েল বেঙ্গল টাইগার ও অন্যান্য প্রাণীও শিকারিদের কারণে বিপন্ন। যেকোনো দেশের জন্যই জীববৈচিত্র্য ও বন্যপ্রাণী অমূল্য সম্পদ। প্রকৃতিতে প্রতিটি প্রাণীরই নির্দিষ্ট ভূমিকা রয়েছে। কোনো একটি প্রাণী বিলুপ্ত হলে পুরো বাস্তুতন্ত্র ক্ষতিগ্রস্ত হয়। তাই সুন্দরবন ও এর বন্যপ্রাণী রক্ষা করা আমাদের জাতীয় দায়িত্ব।",
