    "title": "বাংলার খোকা",
    "sourceText": "মধুমতী নদীর তীরে ছবির মতো সুন্দর একটি গ্রাম টুঙ্গিপাড়া। সেই গ্রামেরই শেখ পরিবারে ১৯২০ সালের ১৭ই মার্চ জন্ম নেয় এক ফুটফুটে শিশু। বাবা-মা ভালোবেসে তাঁর নাম রাখলেন ‘খোকা’। ছোটবেলা থেকেই খোকার মন ছিল অত্যন্ত দয়ার্দ্র ও পরোপকারী। তিনি বন্ধুদের সাথে মাঠে ফুটবল ও কাবাডি খেলতেন, সাঁতার কাটতেন এবং মেঠোপথ ধরে হেঁটে বেড়াতেন। একদিন শীতের সকালে বিদ্যালয় থেকে বাড়ি ফেরার পথে খোকা দেখলেন, পথের ধারে এক বৃদ্ধ মানুষ শীতে থরথর করে কাঁপছে। খোকা এক মুহূর্তও না ভেবে নিজের গায়ের গরম সুতি চাদরটি খুলে সেই বৃদ্ধকে পরিয়ে দিলেন। আরেকদিন বর্ষার বৃষ্টিতে ভিজতে থাকা সহপাঠীকে নিজের ছাতাটি দিয়ে নিজে ভিজে বাড়ি ফিরেছিলেন। বাবা শেখ লুৎফর রহমান ও মা সায়েরা খাতুন খোকার এই মহান মানবপ্রেম দেখে গর্বিত হতেন। এই সাধারণ খোকা-ই বড় হয়ে বাঙালি জাতির অবিসংবাদিত নেতা, সর্বকালের সর্বশ্রেষ্ঠ বাঙালি ও স্বাধীন বাংলাদেশের স্থপতি জাতির পিতা বঙ্গবন্ধু শেখ মুজিবুর রহমান হিসেবে বিশ্বমঞ্চে অমর হয়ে রইলেন।",
