    "sourceText": "১৯৭১ সালের রক্তঝরা মুক্তিযুদ্ধে বহু বীর সেনানী মাতৃভূমির মুক্তির জন্য জীবন বাজি রেখে যুদ্ধ করেছিলেন। তাঁদের মধ্যে সর্বোচ্চ সাহসিকতা ও আত্মদানের স্বীকৃতি হিসেবে ৭ জনকে ‘বীরশ্রেষ্ঠ’ খেতাবে সম্মানিত করা হয়। এঁদের মধ্যে ক্যাপ্টেন মহিউদ্দিন জাহাঙ্গীর চাঁপাইনবাবগঞ্জ ফ্রন্টে সম্মুখ যুদ্ধে নেতৃত্ব দিয়ে শত্রুর গুলিতে শহীদ হন। যশোরের গোয়ালহাটিতে পাকবাহিনীর অতর্কিত আক্রমণের মুখে নিজের জীবনের পরোয়া না করে মেশিনগান চালিয়ে সহযোদ্ধাদের নিরাপদে পিছু হটার সুযোগ করে দিয়েছিলেন ল্যান্সনায়েক নূর মোহাম্মদ শেখ। মারাত্মক আহত অবস্থায়ও তিনি একাই গুলি ছুড়তে ছুড়তে দেশের জন্য শেষ নিঃশ্বাস ত্যাগ করেন। এছাড়া ইঞ্জিনরুম আর্টিফিসার মোহাম্মদ রুহুল আমিন খুলনার রূপসা নদীতে রণতরী ‘পলাশ’-এ শত্রুর বিমান হামলার মুখেও নিজের অবস্থান ছেড়ে যাননি। বীরশ্রেষ্ঠদের এই অমর আত্মত্যাগ ও রক্তের বিনিময়েই ১৯৭১ সালের ১৬ই ডিসেম্বর বাঙালি জাতি ছিনিয়ে আনে লাল-সবুজের স্বাধীন বাংলাদেশ।",
