    "title": "খলিফা হযরত উমর (রা.)",
    "sourceText": "হযরত উমর (রা.) ছিলেন ইসলামের দ্বিতীয় খলিফা। তিনি ছিলেন যেমন ন্যায়পরায়ণ ও কঠোর শাসক, তেমনই কোমল ও প্রজাদরদী। বিশাল মুসলিম জাহানের খলিফা হওয়া সত্ত্বেও তাঁর জীবনযাপন ছিল অত্যন্ত সাধারণ। তিনি ছেঁড়া তালি দেওয়া জামা পরতেন এবং খেজুর পাতার চাটাইয়ে ঘুমাতেন। প্রজারা কীভাবে দিন কাটাচ্ছে তা নিজের চোখে দেখতে তিনি রাতের অন্ধকারে ছদ্মবেশে মদিনার পথে পথে ঘুরে বেড়াতেন। এক রাতে তিনি শহরের বাইরে এক তাঁবুতে শিশুদের কান্নার আওয়াজ শুনতে পেলেন। কাছে গিয়ে দেখলেন, এক অসহায় মা চুলার ওপর পাতিল চাপিয়ে ফুটন্ত পানি নাড়ছেন আর ক্ষুধার্ত শিশুরা খাবারের আশায় তাকিয়ে কাঁদতে কাঁদতে ক্লান্ত হচ্ছে। খলিফা জিজ্ঞেস করায় মহিলা বললেন, ঘরে খাবার নেই, তাই পানি ফুটিয়ে সান্ত্বনা দিচ্ছি যাতে শিশুরা ঘুমিয়ে পড়ে। এ দৃশ্য দেখে খলিফার চোখ পানিতে ভরে গেল। তিনি কালবিলম্ব না করে সরকারি খাদ্যগুদামে ফিরে গেলেন এবং নিজ কাঁধে আটার বস্তা ও ঘি বহন করে সেই তাঁবুতে নিয়ে এলেন। নিজ হাতে খাবার তৈরি করে অনাহারী শিশুদের মুখে তুলে দিয়ে তবেই তিনি স্বস্তির নিঃশ্বাস ফেললেন।",
