    "sourceText": "রংপুরের পায়রাবন্দ গ্রামের সম্ভ্রান্ত জমিদার পরিবারে ১৮৮০ সালের ৯ই ডিসেম্বর জন্মগ্রহণ করেন এক মহীয়সী নারী—বেগম রোকেয়া। সেকালে মুসলিম সমাজে মেয়েদের লেখাপড়া শেখার কোনো সুযোগ ছিল না। পর্দা প্রথার কঠোর কড়াকড়ির কারণে মেয়েদের বাড়ির বাইরে যাওয়ার অনুমতি ছিল না। কিন্তু রোকেয়ার জ্ঞানতৃষ্ণা ছিল সীমাহীন। বড় ভাই ইব্রাহিম সাবেরের অনুপ্রেরণা ও গভীর ভালোবাসায় তিনি গভীর রাতে মোমবাতি জ্বালিয়ে সবার অজান্তে বাংলা ও ইংরেজি শিখতেন। বড় বোন করিমুন্নেসার সহায়তায় তিনি বাংলার চর্চা চালিয়ে যান। বিয়ের পর স্বামী সৈয়দ সাখাওয়াত হোসেনের উৎসাহে রোকেয়ার সাহিত্য ও সমাজসেবার দ্বার আরও উন্মোচিত হয়। স্বামীর মৃত্যুর পর রোকেয়া নারী শিক্ষার বিস্তার ও নারীদের আত্মমর্যাদা প্রতিষ্ঠার লক্ষ্যে প্রতিষ্ঠা করেন ‘সাখাওয়াত মেমোরিয়াল গার্লস স্কুল’। তিনি ঘরে ঘরে গিয়ে অভিভাবকদের বুঝিয়ে বালিকাদের বিদ্যালয়ে নিয়ে আসতেন। ‘সুলতানার স্বপ্ন’, ‘পদ্মরাগ’, ‘অবরোধবাসিনী’ প্রভৃতি কালজয়ী গ্রন্থের মাধ্যমে তিনি সমাজকে জাগিয়ে তুলেছিলেন। তিনিই বাঙালি মুসলিম নারীদের মুক্তির দিশারী ও নারী জাগরণের অগ্রদূত।",
