    "sourceText": "সোনারগাঁও বাংলাদেশের এক অতি গৌরবময় ও ঐতিহাসিক স্থান। ঢাকা থেকে মাত্র প্রায় ২৭ কিলোমিটার দক্ষিণ-পূর্বে নারায়ণগঞ্জ জেলায় এটি অবস্থিত। প্রাচীনকালে সোনারগাঁও ছিল বাংলার মুসলিম রাজধানী। বারো ভূঁইয়াদের প্রধান নেতা ঈসা খাঁ সোনারগাঁও থেকেই পুরো অঞ্চল শাসন করতেন। সোনারগাঁওয়ের অন্যতম আকর্ষণ হলো বিশ্ববিখ্যাত ‘পানাম নগর’। একটিমাত্র সোজা মাটির রাস্তার দুই পাশে গড়ে ওঠা চমৎকার দুই ও তিনতলা প্রাচীন ইউরোপীয় ও মুঘল রীতির বহু অট্টালিকা আজও পর্যটকদের বিমোহিত করে। এছাড়া সোনারগাঁওয়ের গৌরব বাড়িয়েছে ‘শিল্পাচার্য জয়নুল আবেদিন লোকশিল্প জাদুঘর’। শিল্পাচার্য জয়নুল আবেদিন ১৯৭৫ সালে বাংলার সমৃদ্ধ লোকশিল্পকে ধরে রাখতে এটি প্রতিষ্ঠা করেন। এখানে প্রদর্শিত হচ্ছে ঐতিহ্যবাহী নকশিকাঁথা, কাঠের তৈরি নানা খেলনা, শীতলপাটি, পোড়ামাটির তৈজসপত্র এবং পৃথিবীখ্যাত ঐতিহ্যবাহী জামদানি ও মসলিন কাপড়ের নিদর্শন। সোনারগাঁও ভ্রমণ করলে আমাদের প্রাচীন ইতিহাস, স্থাপত্যকলা ও লোকশিল্পের প্রতি গভীর ভালোবাসা ও শ্রদ্ধাবোধ জাগ্রত হয়।",
