    "title": "বীর বিপ্লবী তিতুমীর",
    "sourceText": "তিতুমীর ছিলেন ব্রিটিশবিরোধী স্বাধীনতা সংগ্রামের এক অনন্য প্রতীক। তাঁর প্রকৃত নাম সৈয়দ মীর নিসার আলী। তিনি পশ্চিমবঙ্গের চব্বিশ পরগনা জেলার বারাসাত মহকুমার চাঁদপুর গ্রামে জন্মগ্রহণ করেন। ব্রিটিশ নীলকর ও স্থানীয় অত্যাচারী জমিদারদের শোষণের বিরুদ্ধে তিনি কৃষকদের ঐক্যবদ্ধ করেন। নারকেলবাড়িয়ায় তিনি তৈরি করেন এক দুর্ভেদ্য বাঁশের কেল্লা। ১৮৩১ সালের ১৯ নভেম্বর ব্রিটিশ সেনাপতি কর্নেল স্টুয়ার্টের কামানের গোলার মুখে তিতুমীর ও তাঁর বীর সঙ্গীরা বীরত্বের সাথে লড়াই করে শাহাদাতবরণ করেন। বাঁশের কেল্লা ধ্বংস হলেও তিতুমীরের আত্মত্যাগ ও দেশপ্রেম আজও প্রতিটি বাঙালির হৃদয়ে চিরভাস্বর।",
