export function getPassagesForSubject(classId: string, subjectKey: string): SeenPassageItem[] {
  return SEEN_PASSAGES_POOL.filter(p => p.classId === classId && p.subjectKey === subjectKey);
}

export function findPassageById(id: string): SeenPassageItem | undefined {
  return SEEN_PASSAGES_POOL.find(p => p.id === id);
}

export function matchPassageForLessons(
  classId: string,
  subjectKey: string,
  selectedLessonIds?: string[],
  selectedChapterIds?: string[]
): SeenPassageItem | undefined {
  if (subjectKey !== "english" && subjectKey !== "bangla") return undefined;
  const pool = getPassagesForSubject(classId, subjectKey);
  if (pool.length === 0) return undefined;

  // 1. Try to match by specific lessonId
  if (selectedLessonIds && selectedLessonIds.length > 0) {
    const matched = pool.find(p => p.lessonId && selectedLessonIds.includes(p.lessonId));
    if (matched) return matched;
  }

  // 2. Try to match by unit/chapter
  if (selectedChapterIds && selectedChapterIds.length > 0) {
    const matched = pool.find(p => selectedChapterIds.some(cid => 
      cid === `c4-e-u${p.unitNumber}` ||
      cid === `c5-e-u${p.unitNumber}` ||
      cid === `c3-e-u${p.unitNumber}` ||
      cid === `c5-b-ch${p.unitNumber}` ||
      cid === `c4-b-ch${p.unitNumber}` ||
      cid === `c3-b-ch${p.unitNumber}` ||
      cid.includes(`unit-${p.unitNumber}`) || 
      cid.includes(`chapter-${p.unitNumber}`) || 
      cid.includes(`-u${p.unitNumber}`) ||
      cid.includes(`-ch${p.unitNumber}`) ||
      cid.includes(`b-u${p.unitNumber}`)
    ));
    if (matched) return matched;
  }

  // 3. Fallback to first available passage in pool
  return pool[0];
}
